function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // initial stick figure
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 30, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 30, H/2 + 70);
  ctx.stroke();

  // transformation
  let trans = Math.sin(t);
  if (trans > 0) {
    // transforming into a bird
    ctx.beginPath();
    ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(W/2, H/2 + 20);
    ctx.lineTo(W/2, H/2 + 50);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(W/2, H/2 + 30);
    ctx.lineTo(W/2 - 30 * trans, H/2 + 70);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(W/2, H/2 + 30);
    ctx.lineTo(W/2 + 30 * trans, H/2 + 70);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(W/2 - 30 * trans, H/2 + 70);
    ctx.lineTo(W/2 - 30 * trans - 20 * trans, H/2 + 90);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(W/2 + 30 * trans, H/2 + 70);
    ctx.lineTo(W/2 + 30 * trans + 20 * trans, H/2 + 90);
    ctx.stroke();
  }

  ctx.restore();
}
